import DataLoader from "dataloader";
import fs from "node:fs/promises";
import path from "node:path";
import util from "node:util";
//#region src/env.ts
async function readEnvFile() {
	const envFile = path.resolve(process.cwd(), ".env");
	let content;
	try {
		content = await fs.readFile(envFile, "utf-8");
	} catch {
		return {};
	}
	return util.parseEnv(content);
}
let cachedEnv;
function readEnvFileCached() {
	cachedEnv ??= readEnvFile();
	return cachedEnv;
}
async function readEnv() {
	return {
		GITHUB_GRAPHQL_URL: process.env.GITHUB_GRAPHQL_URL || (await readEnvFileCached()).GITHUB_GRAPHQL_URL || "https://api.github.com/graphql",
		GITHUB_SERVER_URL: process.env.GITHUB_SERVER_URL || (await readEnvFileCached()).GITHUB_SERVER_URL || "https://github.com",
		GITHUB_TOKEN: process.env.GITHUB_TOKEN || (await readEnvFileCached()).GITHUB_TOKEN
	};
}
//#endregion
//#region src/dataloader.ts
const GHDataLoader = new DataLoader(batchLoad, {
	maxBatchSize: 50,
	cacheKeyFn(request) {
		return request.kind === "commit" ? `commit:${request.repo}:${request.commit}` : `pull:${request.repo}:${request.pull}`;
	}
});
async function loadCommitData(options) {
	return await GHDataLoader.load({
		...options,
		kind: "commit"
	});
}
async function loadPullData(options) {
	return await GHDataLoader.load({
		...options,
		kind: "pull"
	});
}
async function batchLoad(requests) {
	const { GITHUB_GRAPHQL_URL, GITHUB_SERVER_URL, GITHUB_TOKEN } = await readEnv();
	if (!GITHUB_TOKEN) throw new Error(`Please create a GitHub personal access token at ${GITHUB_SERVER_URL}/settings/tokens/new?scopes=read:user,repo:status&description=changesets-${(/* @__PURE__ */ new Date()).toISOString().substring(0, 10)} with \`read:user\` and \`repo:status\` permissions and add it as the GITHUB_TOKEN environment variable`);
	const repos = {};
	for (const { repo, ...data } of requests) {
		repos[repo] ??= [];
		repos[repo].push(data);
	}
	let fetchResponse;
	try {
		fetchResponse = await fetch(GITHUB_GRAPHQL_URL, {
			method: "POST",
			headers: { Authorization: `Token ${GITHUB_TOKEN}` },
			body: JSON.stringify({ query: makeQuery(repos) })
		});
	} catch (e) {
		throw new Error("Failed to fetch data from GitHub", { cause: e });
	}
	let data;
	try {
		data = await fetchResponse.json();
	} catch (e) {
		throw new Error("Failed to parse data from GitHub", { cause: e });
	}
	if (data.errors) throw new Error(`Fetched data from GitHub returned errors\n${JSON.stringify(data.errors, null, 2)}`);
	if (!data.data) throw new Error(`Fetched data from GitHub has missing data\n${JSON.stringify(data)}`);
	const repoNames = Object.keys(repos);
	return requests.map((request) => {
		const repoKey = `repo__${repoNames.indexOf(request.repo)}`;
		const dataKey = `${request.kind}__${request.kind === "pull" ? request.pull : request.commit}`;
		return data.data[repoKey]?.[dataKey];
	});
}
function makeQuery(repos) {
	let query = "query {\n";
	let needsCommitFragment = false;
	let needsPullFragment = false;
	const repoNames = Object.keys(repos);
	for (let i = 0; i < repoNames.length; i++) {
		const repoData = repos[repoNames[i]];
		const [owner, name] = repoNames[i].split("/");
		query += `\
  repo__${i}: repository(
    owner: ${JSON.stringify(owner)},
    name: ${JSON.stringify(name)}
  ) {\n`;
		for (const data of repoData) if (data.kind === "commit") {
			needsCommitFragment = true;
			query += `\
    commit__${data.commit}: object(expression: ${JSON.stringify(data.commit)}) {
      ... on Commit {
        ...CommitFragment
      }
    }\n`;
		} else if (data.kind === "pull") {
			needsPullFragment = true;
			query += `\
    pull__${data.pull}: pullRequest(number: ${JSON.stringify(data.pull)}) {
      ...PullFragment
    }\n`;
		}
		query += "  }\n";
	}
	query += "}\n";
	if (needsCommitFragment) query += `\
fragment CommitFragment on Commit {
  commitUrl
  associatedPullRequests(first: 50) {
    nodes {
      number
      url
      mergedAt
      author {
        login
        url
      }
    }
  }
  author {
    user {
      login
      url
    }
  }
}\n`;
	if (needsPullFragment) query += `\
fragment PullFragment on PullRequest {
  url
  author {
    login
    url
  }
  mergeCommit {
    commitUrl
    abbreviatedOid
  }
}\n`;
	return query;
}
//#endregion
//#region src/utils.ts
const validRepoNameRegex = /^[\w.-]+\/[\w.-]+$/;
function validateRepoName(repo) {
	if (!validRepoNameRegex.test(repo)) throw new Error(`Please pass a valid GitHub repository in the form of "userOrOrg/repoName". Received: ${JSON.stringify(repo)}.`);
}
//#endregion
//#region src/get-commit-info.ts
/**
* Get the information of a specific commit in a GitHub repository. Returns
* `undefined` if the commit is not found or the GitHub repository doesn't exist.
*/
async function getCommitInfo(options) {
	validateRepoName(options.repo);
	const data = await loadCommitData({
		commit: options.commit,
		repo: options.repo
	});
	if (data == null) return;
	const pr = data?.associatedPullRequests?.nodes?.sort((a, b) => {
		if (a.mergedAt == null && b.mergedAt == null) return 0;
		if (a.mergedAt == null) return 1;
		if (b.mergedAt == null) return -1;
		const aDate = new Date(a.mergedAt);
		const bDate = new Date(b.mergedAt);
		return aDate.getTime() - bDate.getTime();
	})[0];
	const author = pr?.author ?? data.author?.user;
	return {
		commit: {
			sha: options.commit,
			url: data.commitUrl,
			markdownLink: `[\`${options.commit.slice(0, 7)}\`](${data.commitUrl})`
		},
		author: author ? {
			login: author.login,
			url: author.url,
			markdownLink: `[@${author.login}](${author.url})`
		} : void 0,
		pull: pr ? {
			number: pr.number,
			url: pr.url,
			markdownLink: `[#${pr.number}](${pr.url})`
		} : void 0
	};
}
//#endregion
//#region src/get-pull-request-info.ts
/**
* Get the information of a specific pull request in a GitHub repository. Returns
* `undefined` if the pull request is not found or the GitHub repository doesn't exist.
*/
async function getPullRequestInfo(options) {
	validateRepoName(options.repo);
	const data = await loadPullData({
		pull: options.pull,
		repo: options.repo
	});
	if (data == null) return;
	return {
		pull: {
			number: options.pull,
			url: data.url,
			markdownLink: `[#${options.pull}](${data.url})`
		},
		author: data.author ? {
			login: data.author.login,
			url: data.author.url,
			markdownLink: `[@${data.author.login}](${data.author.url})`
		} : void 0,
		commit: data.mergeCommit ? {
			sha: data.mergeCommit.abbreviatedOid,
			url: data.mergeCommit.commitUrl,
			markdownLink: `[\`${data.mergeCommit.abbreviatedOid.slice(0, 7)}\`](${data.mergeCommit.commitUrl})`
		} : void 0
	};
}
//#endregion
export { getCommitInfo, getPullRequestInfo };
